import React, { useState, useEffect, useRef, useCallback } from 'react';
import { useLocation } from 'react-router-dom';
import styles from '../css/chat.module.css';

const Chat = () => {
  const location = useLocation();
  const { personality, name: chatbotName = '챗봇' } = location.state || {};
  const [userInput, setUserInput] = useState('');
  const [chatHistory, setChatHistory] = useState([]);  // 채팅 기록 상태
  const [currentDateTime, setCurrentDateTime] = useState('');
  const [error, setError] = useState(null);
  const [isRecording, setIsRecording] = useState(false);
  const [isProcessingResponse, setIsProcessingResponse] = useState(false);
  const [audioHtml, setAudioHtml] = useState(null);  // 음성 HTML 상태
  const chatEndRef = useRef(null);
  const mediaRecorderRef = useRef(null);
  const audioChunksRef = useRef([]);

  const getCurrentDateTime = () => {
    const now = new Date();
    const date = now.toLocaleDateString('ko-KR', {
      year: 'numeric',
      month: 'long',
      day: 'numeric',
      weekday: 'long',
    });
    const time = now.toLocaleTimeString('ko-KR', {
      hour: '2-digit',
      minute: '2-digit',
      hour12: false,
    });
    return `${date} ${time}`;
  };

  const getTimeOnly = () => {
    const now = new Date();
    return now.toLocaleTimeString('ko-KR', {
      hour: '2-digit',
      minute: '2-digit',
      hour12: false,
    });
  };

  // // 이전 채팅 기록 가져오기
  // const fetchChatHistory = async () => {
  //   try {
  //     const response = await fetch(`${process.env.REACT_APP_API_URL}/chat-history`);
  //     if (!response.ok) {
  //       throw new Error('채팅 기록을 불러올 수 없습니다.');
  //     }
  //     const data = await response.json();
  //     setChatHistory(data.history);  // MongoDB에서 가져온 채팅 기록 설정
  //   } catch (error) {
  //     console.error('채팅 기록 불러오기 오류:', error);
  //   }
  // };

  const startRecording = () => {
    if (isRecording || isProcessingResponse) return;

    audioChunksRef.current = [];  // 새 녹음 시작 시 초기화

    if (navigator.mediaDevices && navigator.mediaDevices.getUserMedia) {
      navigator.mediaDevices.getUserMedia({ audio: true })
        .then((stream) => {
          mediaRecorderRef.current = new MediaRecorder(stream);

          mediaRecorderRef.current.ondataavailable = (event) => {
            audioChunksRef.current.push(event.data);
          };

          mediaRecorderRef.current.onstop = async () => {
            const audioBlob = new Blob(audioChunksRef.current, { type: 'audio/mp3' });
            const audioData = await audioBlob.arrayBuffer();
            const formData = new FormData();
            formData.set('chatbot_name', chatbotName);
            formData.set('personality', personality);
            formData.set('file', new Blob([audioData]), 'audio.mp3');

            try {
              setIsProcessingResponse(true);
              const response = await fetch(`${process.env.REACT_APP_API_URL}/chat-audio`, {
                method: 'POST',
                body: formData,
              });

              if (!response.ok) {
                throw new Error('음성 파일 전송 오류');
              }

              const data = await response.json();
              const chatbotMessage = data.response;
              const newAudioHtml = data.audio_html;
              const recognizedText = data.transcribed_text;

              const sentTime = getTimeOnly();
              setChatHistory((prevHistory) => [
                ...prevHistory,
                { sender: '사용자', message: recognizedText, time: sentTime },
              ]);

              const receivedTime = getTimeOnly();
              setChatHistory((prevHistory) => [
                ...prevHistory,
                { sender: chatbotName, message: chatbotMessage, time: receivedTime },
              ]);

              setAudioHtml(newAudioHtml);
              setUserInput(''); 
            } catch (error) {
              setError(error.message);
            } finally {
              setIsProcessingResponse(false);
            }
          };

          mediaRecorderRef.current.start();
          setIsRecording(true);
        })
        .catch((err) => {
          console.error('녹음 권한을 요청할 수 없습니다.', err);
        });
    }
  };

  const stopRecording = () => {
    if (!isRecording) return;

    if (mediaRecorderRef.current) {
      mediaRecorderRef.current.stop();
    }
    setIsRecording(false);
    audioChunksRef.current = [];
  };

  const handleSendMessage = async () => {
    if (isRecording || isProcessingResponse || userInput.trim() === '') return;

    const sentTime = getTimeOnly();
    const newMessage = { sender: '사용자', message: userInput, time: sentTime };
    setChatHistory((prevHistory) => [...prevHistory, newMessage]);
    setUserInput('');  // 입력 필드 초기화

    try {
      setIsProcessingResponse(true);
      const response = await fetch(`${process.env.REACT_APP_API_URL}/chat`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          chatbotName: chatbotName,
          user_input: userInput,
          personality: personality,
        }),
      });

      if (!response.ok) {
        const errorData = await response.json();
        throw new Error(errorData.detail || '서버 응답 오류');
      }

      const data = await response.json();
      const chatbotMessage = data.response;
      const newAudioHtml = data.audio_html;

      const receivedTime = getTimeOnly();
      setChatHistory((prevHistory) => [
        ...prevHistory,
        { sender: chatbotName, message: chatbotMessage, time: receivedTime },
      ]);

      setAudioHtml(newAudioHtml);
    } catch (error) {
      console.error('Error fetching chatbot response:', error);
      if (error.message.includes('부적절한 내용')) {
        alert('부적절한 내용은 사용할 수 없습니다. 다시 입력해주세요.');
        setChatHistory((prevHistory) => prevHistory.slice(0, -1));  // 마지막 메시지 제거
      } else {
        setError(error.message);
      }
    } finally {
      setIsProcessingResponse(false);
    }
  };

  const handleKeyDown = (e) => {
    if (e.key === 'Enter') {
      handleSendMessage();
    }
  };

  const displayErrorMessage = useCallback(() => {
    return error ? <div className={styles.errorMessage}>{error}</div> : null;
  }, [error]);

  useEffect(() => {
    fetchChatHistory();  // 채팅 기록 가져오기
    const interval = setInterval(() => {
      setCurrentDateTime(getCurrentDateTime());
    }, 1000);
    return () => clearInterval(interval);
  }, []);

  useEffect(() => {
    if (chatEndRef.current) {
      chatEndRef.current.scrollIntoView({ behavior: 'smooth' });
    }
  }, [chatHistory]);

  return (
    <div className={styles.chatContainer}>
      <div className={styles.chatDataTime}>
        <strong>{currentDateTime}</strong>
      </div>
      <div className={styles.chatHistory}>
        {chatHistory.map((chat, index) => (
          <div
            key={index}
            className={chat.sender === '사용자' ? styles.chatMessageUser : styles.chatMessageChatbot}
          >
            <strong>{chat.sender === '사용자' ? '사용자' : chatbotName}:</strong>
            <div>{chat.message}</div>
            <div className={chat.sender === '사용자' ? styles.chatTimeUser : styles.chatTimeChatbot}>
              <em>{chat.time}</em>
            </div>
          </div>
        ))}
        <div ref={chatEndRef} />
      </div>
      <div className={styles.chatInputArea}>
        <input
          type="text"
          value={userInput}
          onChange={(e) => setUserInput(e.target.value)}
          onKeyDown={handleKeyDown}
          disabled={isRecording || isProcessingResponse}
        />
        <button
          className={styles.chatSendButton}
          onClick={handleSendMessage}
          disabled={isRecording || isProcessingResponse}
        >
          전송
        </button>
        <button
          className={styles.voiceButton}
          onClick={isRecording ? stopRecording : startRecording}
        >
          {isRecording ? '녹음 중지' : '음성 인식 시작'}
        </button>
      </div>
      {displayErrorMessage()}
      {!isRecording && !isProcessingResponse && audioHtml && userInput.trim() === '' && (
        <div dangerouslySetInnerHTML={{ __html: audioHtml }} />
      )}
    </div>
  );
};

export default Chat;
